import{_ as d,l as s,o as e,c as l,v as o,p as n,x as r,d as i,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"数据冒险与转发","description":"","frontmatter":{"title":"数据冒险与转发","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/data-hazard-forward.md","filePath":"cs/data-hazard-forward.md","lastUpdated":1789023840000}'),E={name:"cs/data-hazard-forward.md"};function h(A,a,u,_,m,M){const t=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="数据冒险与转发" tabindex="-1">数据冒险与转发 <a class="header-anchor" href="#数据冒险与转发" aria-label="Permalink to &quot;数据冒险与转发&quot;">​</a></h1><div class="epigraph"><p>后指令要的操作数，可能还停在前指令的流水线寄存器里；从那里抄过来，不必等写回。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p><a href="/cs/structural-hazard">上一课</a>用分体存储和两读一写堆拿掉了结构冲突。本课不重讲端口日历。缺口是：即使硬件够用，后一条指令在 ID 读寄存器时，前一条的结果可能还在 EX 或 MEM，堆里仍是旧值。本课只处理这类数据冒险，并用转发把结果从级间寄存器送到 ALU 输入。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>add x1, x2, x3</code> 后面紧跟 <code>sub x4, x1, x5</code>。按五级时间表，<code>add</code> 在 WB 才写入 <code>x1</code>，<code>sub</code> 早两拍就在 ID 读堆。读到的是旧 <code>x1</code>，ISA 的顺序语义被打破。缺口不是再加一个 ALU，而是承认<strong>流水线里存在尚未写回的「未来寄存器值」</strong>，必须在 ALU 使用前接到正确来源。</p><p>load 更苛刻：数据要到 MEM 结束才出现，下一条若在 EX 就要用，转发也来不及，必须停一拍。本课把这条 load-use 停顿钉死，不把停顿推广到所有相关。</p><p><span class="marginnote">相关按读写分类：RAW 是真依赖，WAR/WAW 在五级顺序流水线里几乎不出现，因为写固定在 WB、读在 ID。乱序核里它们会回来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>比较 EX/MEM 与 MEM/WB 流水线寄存器中的目的寄存器号，与当前 EX 级指令的源寄存器号。若匹配且前指令确实要写寄存器，把 ALU 或存储器刚得到的值 mux 进 ALU 输入，而不是用堆读出口。这就是转发（旁路）。</p><p>load 后紧跟使用：转发源在 MEM，使用者已进入 EX，路径差一拍。检测 load-use，在 ID/EX 插入气泡，让 load 先走到 MEM，下一拍再转发。</p>',10)),(e(),n(p,null,{default:r(()=>[c(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20LR%0A%20%20EXM%5B%22EX%2FMEM%20%E7%BB%93%E6%9E%9C%22%5D%20--%3E%20MUX%5B%22ALU%20%E8%BE%93%E5%85%A5%20mux%22%5D%0A%20%20MW%5B%22MEM%2FWB%20%E7%BB%93%E6%9E%9C%22%5D%20--%3E%20MUX%0A%20%20RF%5B%22%E5%AF%84%E5%AD%98%E5%99%A8%E5%A0%86%E8%AF%BB%E5%8F%A3%22%5D%20--%3E%20MUX%0A%20%20MUX%20--%3E%20ALU%5B%22EX%20ALU%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>转发恢复的是 ISA 看见的 RAW 顺序，不改变五级划分。编译器仍可插入无关指令填 load-use 槽，那是软件调度；硬件必须在任意指令对上正确。控制冒险尚未进场：本课假定 PC 顺序加 4。</p><p>检测逻辑是组合比较器加 mux 选择，延迟加在 EX 前。设计若把时钟再压紧，转发路径会成为新的关键路径；那是实现约束，不是语义缺口。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不处理分支用到的条件与目标——它们在 EX 才齐，属于<a href="/cs/control-hazard-predict">控制冒险与分支预测</a>。也不引入寄存器重命名：五级里 WAR/WAW 被固定写回点挡住。浮点多周期运算的相关，后课 Tomasulo 才系统处理。</p><p>后课默认：整数 ALU 相关用转发消除；load-use 仍可能停一拍。谈到「数据冒险」，先指 RAW。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>数据冒险是后指令要用的值还在流水线里，堆尚未更新。</li><li>转发从 EX/MEM、MEM/WB 旁路到 ALU；load-use 仍要一拍气泡。</li><li>控制相关是后课的缺口。</li><li>出处：Patterson and Hennessy, <em>COD</em> RISC-V 数据冒险与转发。</li></ul>',8))])}const B=d(E,[["render",h]]);export{x as __pageData,B as default};
